// CandidateServiceServer is the server API for CandidateService service.
// All implementations must embed UnimplementedCandidateServiceServer
// for forward compatibility.
type CandidateServiceServer interface {
	ListCandidates(context.Context, *ListCandidatesRequest) (*ListCandidatesResponse, error)
	GetCandidate(context.Context, *CandidateRequest) (*Candidate, error)
	CreateCandidate(context.Context, *CandidateInput) (*Candidate, error)
	UpdateCandidate(context.Context, *UpdateCandidateRequest) (*Candidate, error)
	// Hard delete with every panel (as NüHabit).
	DeleteCandidate(context.Context, *CandidateRequest) (*MessageResponse, error)
	// Moves a candidate to any pipeline status and logs the change.
	MoveCandidateStage(context.Context, *MoveStageRequest) (*MoveStageResponse, error)
	// Kanban board: one column per pipeline status.
	GetPipeline(context.Context, *GetPipelineRequest) (*Pipeline, error)
	// Candidates in talent_pool (and archived when asked).
	ListTalentPool(context.Context, *ListTalentPoolRequest) (*ListCandidatesResponse, error)
	GetRecruitmentSummary(context.Context, *emptypb.Empty) (*RecruitmentSummary, error)
	// Analytics page: KPIs with a comparison period, weekly trend, funnel,
	// stage durations, sources, openings, assessments and offers.
	GetRecruitmentDashboard(context.Context, *RecruitmentDashboardRequest) (*RecruitmentDashboard, error)
	ListNotes(context.Context, *CandidateRequest) (*ListNotesResponse, error)
	AddNote(context.Context, *AddNoteRequest) (*CandidateNote, error)
	ListActivities(context.Context, *CandidateRequest) (*ListActivitiesResponse, error)
	GetScreening(context.Context, *CandidateRequest) (*ScreeningResponse, error)
	SaveScreening(context.Context, *SaveScreeningRequest) (*Screening, error)
	// CV upload (pdf, doc, docx, jpg, png; 10 MB).
	UploadCv(context.Context, *UploadCvRequest) (*Candidate, error)
	DeleteCv(context.Context, *CandidateRequest) (*Candidate, error)
	DownloadCv(context.Context, *CandidateRequest) (*FileContent, error)
	GetAiAnalysis(context.Context, *CandidateRequest) (*AiAnalysisResponse, error)
	// Scores the candidate profile against the job opening (OpenRouter, or
	// the deterministic mock without a key).
	AnalyzeCandidate(context.Context, *CandidateRequest) (*AiAnalysis, error)
	// Pipeline report PDF, available from the Offer stage.
	DownloadPipelineReport(context.Context, *CandidateRequest) (*FileContent, error)
	mustEmbedUnimplementedCandidateServiceServer()
}

